    case FieldId::FRC_2025_REEFSCAPE_ANDY_MARK:
      return FIELD_FRC_2025_REEFSCAPE_ANDY_MARK;
    case FieldId::FTC_2025_2026_DECODE:
      return FIELD_FTC_2025_2026_DECODE;
    case FieldId::FRC_2026_REBUILT_WELDED:
