std::string_view GetFieldName(FieldId field) {
  return GetFieldData(field).name;
}

Field GetField(FieldId field) {
  const auto& data = GetFieldData(field);
  Field result;
  result.m_name = data.name;
  result.m_season = data.season;
  result.m_game = data.game;
  if (data.fieldImage != nullptr) {
    result.m_image.emplace(data.fieldImage, data.top, data.left,
                           data.bottom, data.right);
  }
  result.m_fieldLength = wpi::units::meter_t{data.length};
  result.m_fieldWidth = wpi::units::meter_t{data.width};
  result.m_program = data.program;
  result.m_resourceFile = data.resourceFile;
  result.m_hasTags = data.hasTags;
  result.m_tags = data.tags;
  result.m_getJson = data.getJson;
  return result;
}

